-- Schema-only snapshot of the existing SQLite application. No account/order/secret data.
-- Source HEAD: 282d1b2c1b01fdbfec126e9432ba1396cfb26ddc
-- Generated by openStore() on an isolated empty directory; not a PostgreSQL migration.
PRAGMA foreign_keys=ON;
CREATE TABLE account_tokens(hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),kind TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE addresses(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),recipient TEXT NOT NULL,phone TEXT NOT NULL,address TEXT NOT NULL,region TEXT NOT NULL, country TEXT NOT NULL DEFAULT '', province_code TEXT NOT NULL DEFAULT '', province_name TEXT NOT NULL DEFAULT '', ward_code TEXT NOT NULL DEFAULT '', ward_name TEXT NOT NULL DEFAULT '', address_line TEXT NOT NULL DEFAULT '', address_version TEXT NOT NULL DEFAULT '');
CREATE TABLE analytics_events(id INTEGER PRIMARY KEY,event TEXT NOT NULL,product_id INTEGER,created TEXT NOT NULL);
CREATE TABLE audit_log(id INTEGER PRIMARY KEY,actor INTEGER,action TEXT NOT NULL,target TEXT NOT NULL,note TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE chat_messages(id INTEGER PRIMARY KEY,session_id TEXT NOT NULL REFERENCES chat_sessions(id),role TEXT NOT NULL,body TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE chat_sessions(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),created TEXT NOT NULL);
CREATE TABLE checkout_requests(user_id INTEGER NOT NULL REFERENCES users(id),request_key TEXT NOT NULL,fingerprint TEXT NOT NULL,response TEXT NOT NULL,PRIMARY KEY(user_id,request_key));
CREATE TABLE commerce_settings(id INTEGER PRIMARY KEY CHECK(id=1),value TEXT NOT NULL);
CREATE TABLE coupons(code TEXT PRIMARY KEY,kind TEXT NOT NULL,value INTEGER NOT NULL,min_total INTEGER NOT NULL,max_discount INTEGER NOT NULL,starts INTEGER NOT NULL,ends INTEGER NOT NULL,limit_total INTEGER NOT NULL,limit_user INTEGER NOT NULL,product_ids TEXT NOT NULL DEFAULT '[]',active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE demo_catalog_seed(sku TEXT PRIMARY KEY,product_id INTEGER);
CREATE TABLE inventory_movements(id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL,variant_id INTEGER,delta INTEGER NOT NULL,reason TEXT NOT NULL,order_id INTEGER,actor INTEGER,created TEXT NOT NULL);
CREATE TABLE loyalty_ledger(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),order_id INTEGER NOT NULL REFERENCES orders(id),reason TEXT NOT NULL,points INTEGER NOT NULL,created TEXT NOT NULL,UNIQUE(order_id,reason));
CREATE TABLE mfa_recovery(hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE notification_outbox(id INTEGER PRIMARY KEY,recipient TEXT NOT NULL,subject TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',attempts INTEGER NOT NULL DEFAULT 0,created TEXT NOT NULL,sent TEXT);
CREATE TABLE order_events(id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id),actor INTEGER,kind TEXT NOT NULL,note TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE orders(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),created TEXT NOT NULL,status TEXT NOT NULL,total INTEGER NOT NULL,shipping INTEGER NOT NULL,payment TEXT NOT NULL,recipient TEXT NOT NULL,address TEXT NOT NULL,phone TEXT NOT NULL,items TEXT NOT NULL,bank TEXT NOT NULL, payment_status TEXT NOT NULL DEFAULT 'unpaid', discount INTEGER NOT NULL DEFAULT 0, coupon TEXT NOT NULL DEFAULT '', points_used INTEGER NOT NULL DEFAULT 0, email TEXT NOT NULL DEFAULT '', region TEXT NOT NULL DEFAULT '', guest_hash TEXT, expires INTEGER, stock_released INTEGER NOT NULL DEFAULT 0, country TEXT NOT NULL DEFAULT '', province_code TEXT NOT NULL DEFAULT '', province_name TEXT NOT NULL DEFAULT '', ward_code TEXT NOT NULL DEFAULT '', ward_name TEXT NOT NULL DEFAULT '', address_line TEXT NOT NULL DEFAULT '', address_version TEXT NOT NULL DEFAULT '');
CREATE TABLE payment_intents(reference TEXT PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id),amount INTEGER NOT NULL,created INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE payment_transactions(id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id),kind TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),reference TEXT NOT NULL UNIQUE,actor INTEGER,created TEXT NOT NULL);
CREATE TABLE product_variants(id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL REFERENCES products(id),sku TEXT NOT NULL UNIQUE,label TEXT NOT NULL,price INTEGER NOT NULL CHECK(price>=0),stock INTEGER NOT NULL CHECK(stock>=0),active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE products(id INTEGER PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL,description TEXT NOT NULL,price INTEGER NOT NULL CHECK(price>=0),stock INTEGER NOT NULL CHECK(stock>=0),image TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,details TEXT NOT NULL DEFAULT '{}');
CREATE TABLE return_requests(id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL UNIQUE REFERENCES orders(id),reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'requested',note TEXT NOT NULL DEFAULT '',restocked INTEGER NOT NULL DEFAULT 0,created TEXT NOT NULL);
CREATE TABLE reviews(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),product_id INTEGER NOT NULL REFERENCES products(id),rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created TEXT NOT NULL,UNIQUE(user_id,product_id));
CREATE TABLE sessions(token TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),csrf TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE settings(id INTEGER PRIMARY KEY CHECK(id=1),value TEXT NOT NULL);
CREATE TABLE shipments(order_id INTEGER PRIMARY KEY REFERENCES orders(id),carrier TEXT NOT NULL,tracking TEXT NOT NULL,url TEXT NOT NULL,status TEXT NOT NULL,updated TEXT NOT NULL);
CREATE TABLE users(id INTEGER PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'customer', verified INTEGER NOT NULL DEFAULT 0, totp_secret TEXT, totp_pending TEXT, totp_last INTEGER NOT NULL DEFAULT -1);
CREATE TABLE wishlists(user_id INTEGER NOT NULL REFERENCES users(id),product_id INTEGER NOT NULL REFERENCES products(id),PRIMARY KEY(user_id,product_id));
CREATE INDEX idx_events_order ON order_events(order_id,id);
CREATE INDEX idx_orders_status ON orders(status,created);
CREATE INDEX idx_orders_user ON orders(user_id,id);
CREATE INDEX idx_outbox_status ON notification_outbox(status,id);
